		g.fillRoundRect(0, 0, 7, 7, 3, 3);
		g.setColor(new Color(58, 148, 58));
		g.fillRoundRect(9, 0, 7, 7, 3, 3);
		g.setColor(new Color(61, 99, 185));
		g.fillRoundRect(0, 9, 7, 7, 3, 3);
		g.setColor(new Color(212, 160, 23));
